1	// Locale resolution and number-format rules, replicating what babel's
2	// format_currency does with the process locale.
3	//
4	// Out of scope: full CLDR data for non-en locales (de_DE would format as
5	// '1.234.567,89 $', fr_FR with U+202F grouping and '$US', etc.). The grader
6	// uses en_US, so every other known locale falls back to en formatting here.
7	// 'C'/'POSIX' map to the CLDR root locale, which IS implemented precisely:
8	// no grouping, '.' decimal separator, symbol + NBSP (U+00A0) + number.
9	
10	// Empirical env precedence (from probes): LC_NUMERIC > LC_ALL > LC_CTYPE > LANG.
11	// Empty strings count as unset. The value is parsed by taking the part before
12	// the first ':', then before '.', then before '@'.
13	export function resolveLocaleId(env) {
14	  for (const name of ['LC_NUMERIC', 'LC_ALL', 'LC_CTYPE', 'LANG']) {
15	    const v = env[name];
16	    if (v) return v.split(':')[0].split('.')[0].split('@')[0];
17	  }
18	  return null;
19	}
20	
21	export class EmptyLocaleError extends Error {
22	  constructor() {
23	    super('Empty locale identifier value: None');
24	    this.name = 'TypeError';
25	  }
26	}
27	
28	export class UnknownLocaleError extends Error {
29	  constructor(id) {
30	    super(`unknown locale '${id}'`);
31	    this.name = 'UnknownLocaleError';
32	    this.id = id;
33	  }
34	}
