36	// ISO 639-1 language codes, used only to distinguish "known locale we don't
37	// have CLDR data for" (fall back to en) from a bogus identifier (babel raises
38	// UnknownLocaleError, exit 1).
39	const ISO_639_1 = new Set((
40	  'aa ab ae af ak am an ar as av ay az ba be bg bh bi bm bn bo br bs ca ce ch co cr cs cu cv cy ' +
41	  'da de dv dz ee el en eo es et eu fa ff fi fj fo fr fy ga gd gl gn gu gv ha he hi ho hr ht hu ' +
42	  'hy hz ia id ie ig ii ik io is it iu ja jv ka kg ki kj kk kl km kn ko kr ks ku kv kw ky la lb ' +
43	  'lg li ln lo lt lu lv mg mh mi mk ml mn mr ms mt my na nb nd ne ng nl nn no nr nv ny oc oj om ' +
44	  'or os pa pi pl ps pt qu rm rn ro ru rw sa sc sd se sg si sk sl sm sn so sq sr ss st su sv sw ' +
45	  'ta te tg th ti tk tl tn to tr ts tt tw ty ug uk ur uz ve vi vo wa wo xh yi yo za zh zu'
46	).split(' '));
47	
48	const RULES_EN = { grouping: true, symbolGap: '' };
49	const RULES_ROOT = { grouping: false, symbolGap: ' ' };
50	
51	// Returns the format rules for a resolved locale identifier.
52	// Throws EmptyLocaleError (null id) or UnknownLocaleError (bogus id).
53	export function rulesForLocale(id) {
54	  if (id === null) throw new EmptyLocaleError();
55	  if (id === '' || id === 'C' || id === 'POSIX') return RULES_ROOT;
56	  const lang = id.split(/[_-]/)[0].toLowerCase();
57	  if (lang === 'en') return RULES_EN;
58	  if (ISO_639_1.has(lang)) return RULES_EN; // non-en CLDR locales: en fallback (see header)
59	  throw new UnknownLocaleError(id);
60	}

1	// Decimal arithmetic on digit strings, replicating the Python pipeline
2	// moneyed uses: Decimal(str(float_value)) quantized with ROUND_HALF_EVEN.
3	// String(v) in JS yields the same shortest round-trip digits as Python's
4	// repr(float); only the exponent-notation thresholds differ, so we normalize
5	// both plain and e-notation into (sign, digits, exponent) where
6	// value = digits * 10^exponent.
7	
8	// Parse a string the way Python's float() does.
9	// Accepts: surrounding whitespace, optional sign, '1.5', '5.', '.5', '1e3',
10	// '1.5E-2', 'inf'/'infinity'/'nan' (case-insensitive), and single underscores
11	// between digits ('1_000'). Returns { ok: true, value } or { ok: false }.
12	export function parsePythonFloat(text) {
13	  let t = String(text).trim();
14	  t = t.replace(/(?<=\d)_(?=\d)/g, '');
15	  const m = /^([+-]?)(?:(\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|inf(?:inity)?|nan)$/i.exec(t);
16	  if (!m) return { ok: false };
17	  if (/nan$/i.test(t)) return { ok: true, value: NaN }; // sign of nan is lost in Python's str()
18	  if (/inf(?:inity)?$/i.test(t)) return { ok: true, value: m[1] === '-' ? -Infinity : Infinity };
19	  return { ok: true, value: Number(t) };
20	}
21	
22	// Split a finite double into its shortest-round-trip decimal digits.
23	// Returns { neg, digits, exp } with value = digits * 10^exp.
24	export function doubleToDecimal(v) {
25	  const neg = v < 0 || Object.is(v, -0);
26	  const s = String(Math.abs(v));
27	  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/.exec(s);
28	  const frac = m[2] || '';
29	  const digits = (m[1] + frac).replace(/^0+(?=\d)/, '');
30	  const exp = (m[3] ? parseInt(m[3], 10) : 0) - frac.length;
31	  return { neg, digits, exp };
32	}
33	
34	// Numeric comparison of two decimal digit strings (leading zeros tolerated).
35	function cmpDigits(a, b) {
36	  a = a.replace(/^0+/, '') || '0';
37	  b = b.replace(/^0+/, '') || '0';
38	  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
39	  return a < b ? -1 : a > b ? 1 : 0;
40	}
41	
42	function incrementDigits(digits) {
43	  let out = '';
44	  let carry = 1;
45	  for (let i = digits.length - 1; i >= 0; i--) {
46	    const d = digits.charCodeAt(i) - 48 + carry;
47	    if (d === 10) {
48	      out = '0' + out;
49	    } else {
50	      out = String.fromCharCode(48 + d) + out;
51	      carry = 0;
52	    }
53	  }
54	  return carry ? '1' + out : out;
55	}
56	
57	// Quantize a decimal to `q` fraction digits with ROUND_HALF_EVEN
58	// (banker's rounding), exactly like Decimal.quantize in the reference.
59	// Returns { intStr, fracStr } (fracStr has exactly q chars, empty when q=0).
60	export function quantizeHalfEven(dec, q) {
61	  const shift = dec.exp + q;
62	  let kept;
63	  let dropped;
64	  if (shift >= 0) {
65	    kept = dec.digits + '0'.repeat(shift);
66	    dropped = '';
67	  } else {
68	    const cut = dec.digits.length + shift;
69	    if (cut > 0) {
70	      kept = dec.digits.slice(0, cut);
71	      dropped = dec.digits.slice(cut);
72	    } else {
73	      kept = '';
74	      dropped = '0'.repeat(-cut) + dec.digits;
75	    }
76	  }
77	  if (dropped) {
78	    const half = '5' + '0'.repeat(dropped.length - 1);
79	    const c = cmpDigits(dropped, half);
80	    const lastKept = kept.length ? kept.charCodeAt(kept.length - 1) - 48 : 0;
81	    if (c > 0 || (c === 0 && lastKept % 2 === 1)) kept = incrementDigits(kept);
82	  }
83	  const padded = kept.padStart(q + 1, '0');
84	  const intStr = padded.slice(0, padded.length - q) || '0';
85	  const fracStr = q > 0 ? padded.slice(-q) : '';
86	  return { intStr, fracStr };
87	}
