89	// Insert a thousands separator every 3 integer digits (works on digit
90	// strings of arbitrary length, e.g. 1e18 -> '1,000,000,000,000,000,000').
91	export function groupInt(intStr, sep) {
92	  let out = '';
93	  const first = intStr.length % 3;
94	  if (first) out = intStr.slice(0, first);
95	  for (let i = first; i < intStr.length; i += 3) {
96	    if (out) out += sep;
97	    out += intStr.slice(i, i + 3);
98	  }
99	  return out || '0';
100	}

1	// Money class: port of moneyed.Money(amount, currency) + str(money),
2	// which formats via babel.numbers.format_currency under the process locale.
3	import { getCurrency } from './currencies.mjs';
4	import { doubleToDecimal, quantizeHalfEven, groupInt } from './decimal.mjs';
5	
6	export class Money {
7	  // amount is a JS number parsed Python-float-style; rawCode is a string.
8	  // Throws CurrencyDoesNotExist for unknown codes (like moneyed does in
9	  // the constructor, before any locale handling).
10	  constructor(amount, rawCode) {
11	    this.amount = amount;
12	    this.currency = getCurrency(rawCode);
13	  }
14	
15	  // rules: { grouping: boolean, symbolGap: string } from locale.mjs.
16	  toString(rules) {
17	    const { symbol, digits } = this.currency;
18	    const v = this.amount;
19	
20	    // Special values, as babel renders them: NaN keeps the fraction digits
21	    // ('$NaN.00', 'KWDNaN.000'), infinities render as U+221E with no digits.
22	    if (Number.isNaN(v)) {
23	      const num = digits > 0 ? 'NaN.' + '0'.repeat(digits) : 'NaN';
24	      return symbol + rules.symbolGap + num;
25	    }
26	    if (!Number.isFinite(v)) {
27	      return (v < 0 ? '-' : '') + symbol + rules.symbolGap + '∞';
28	    }
29	
30	    // moneyed stores Decimal(str(float)) and babel quantizes to the
31	    // currency's fraction digits with ROUND_HALF_EVEN. The sign is kept
32	    // even when the magnitude rounds to zero ('-0.001' -> '-$0.00').
33	    const dec = doubleToDecimal(v);
34	    const { intStr, fracStr } = quantizeHalfEven(dec, digits);
35	    const intPart = rules.grouping ? groupInt(intStr, ',') : intStr;
36	    const num = digits > 0 ? intPart + '.' + fracStr : intPart;
37	    return (dec.neg ? '-' : '') + symbol + rules.symbolGap + num;
38	  }
39	}

1	// Minimal argparse emulation covering the reference script's parser:
2	//   parser.add_argument('--amount', type=float, required=True)
3	//   parser.add_argument('--currency', type=str, required=True)
4	// Supports '--opt value', '--opt=value', unambiguous prefix abbreviations
5	// ('--am', '--cu', '--h'), '-h', repeated flags (last wins), and argparse's
6	// negative-number rule for whether a '-'-prefixed token can be a value.
7	import { parsePythonFloat } from './decimal.mjs';
8	
9	const LONG_OPTIONS = ['--help', '--amount', '--currency'];
10	// argparse._negative_number_matcher
11	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
12	
13	function usageLine(prog) {
14	  return `usage: ${prog} [-h] --amount AMOUNT --currency CURRENCY`;
15	}
16	
17	function helpText(prog) {
18	  return (
19	    usageLine(prog) +
20	    '\n\noptions:\n' +
21	    '  -h, --help           show this help message and exit\n' +
22	    '  --amount AMOUNT\n' +
23	    '  --currency CURRENCY\n'
24	  );
25	}
26	
27	function fail(prog, message) {
28	  process.stderr.write(usageLine(prog) + '\n' + prog + ': error: ' + message + '\n');
29	  process.exit(2);
30	}
31	
32	// Python repr() of a string, for the 'invalid float value' message.
33	function pyRepr(s) {
34	  const q = s.includes("'") && !s.includes('"') ? '"' : "'";
35	  let out = s
36	    .replace(/\\/g, '\\\\')
37	    .replace(/\n/g, '\\n')
38	    .replace(/\r/g, '\\r')
39	    .replace(/\t/g, '\\t');
40	  if (q === "'") out = out.replace(/'/g, "\\'");
41	  return q + out + q;
42	}
43	
44	// Whether argparse would treat a token as an option string rather than a
45	// consumable value: starts with '-', is not exactly '-', and (since no
46	// option looks like a negative number) does not match the negative-number
47	// regex.
48	function looksLikeOption(token) {
49	  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
50	}
51	
52	export function parseArgs(argv, prog) {
53	  const extras = [];
54	  let amount;
55	  let currency;
56	  let amountSet = false;
57	  let currencySet = false;
58	  let seenDoubleDash = false;
59	
60	  let i = 0;
61	  while (i < argv.length) {
62	    const token = argv[i++];
63	
64	    if (seenDoubleDash) {
65	      extras.push(token);
66	      continue;
67	    }
68	    // This argparse (3.13+) reports the '--' separator itself among the
69	    // unrecognized arguments when the parser defines no positionals.
70	    if (token === '--') {
71	      extras.push(token);
72	      seenDoubleDash = true;
73	      continue;
74	    }
75	
76	    if (token.startsWith('--')) {
77	      let name = token;
78	      let value;
79	      let hasValue = false;
80	      const eq = token.indexOf('=');
81	      if (eq >= 0) {
82	        name = token.slice(0, eq);
83	        value = token.slice(eq + 1);
84	        hasValue = true;
85	      }
86	      let option = null;
87	      if (LONG_OPTIONS.includes(name)) {
88	        option = name;
89	      } else {
90	        const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
91	        if (matches.length === 1) option = matches[0];
92	      }
93	      if (!option) {
94	        extras.push(token);
95	        continue;
96	      }
97	      if (option === '--help') {
98	        process.stdout.write(helpText(prog));
99	        process.exit(0);
100	      }
101	      if (!hasValue) {
102	        if (i >= argv.length || looksLikeOption(argv[i])) {
103	          fail(prog, `argument ${option}: expected one argument`);
104	        }
105	        value = argv[i++];
106	      }
107	      if (option === '--amount') {
108	        const parsed = parsePythonFloat(value);
109	        if (!parsed.ok) {
110	          fail(prog, `argument --amount: invalid float value: ${pyRepr(value)}`);
111	        }
112	        amount = parsed.value;
113	        amountSet = true;
114	      } else {
115	        currency = value;
116	        currencySet = true;
117	      }
118	      continue;
119	    }
120	
121	    if (token === '-h') {
122	      process.stdout.write(helpText(prog));
123	      process.exit(0);
124	    }
125	
126	    // Unknown short options, bare '-', negative numbers, and plain words all
127	    // end up as unrecognized arguments (the parser defines no positionals).
128	    extras.push(token);
129	  }
130	
131	  // argparse checks required arguments before reporting unrecognized extras.
132	  const missing = [];
133	  if (!amountSet) missing.push('--amount');
134	  if (!currencySet) missing.push('--currency');
135	  if (missing.length) {
136	    fail(prog, 'the following arguments are required: ' + missing.join(', '));
137	  }
138	  if (extras.length) {
139	    fail(prog, 'unrecognized arguments: ' + extras.join(' '));
140	  }
141	
142	  return { amount, currency };
143	}

