10	import { parseArgs } from './argparse.mjs';
11	import { Money } from './money.mjs';
12	import { CurrencyDoesNotExist } from './currencies.mjs';
13	import {
14	  resolveLocaleId,
15	  rulesForLocale,
16	  EmptyLocaleError,
17	  UnknownLocaleError,
18	} from './locale.mjs';
19	
20	const prog = process.argv[1].split('/').pop();
21	const args = parseArgs(process.argv.slice(2), prog);
22	
23	// Money() construction happens before locale handling in the Python script,
24	// so an unknown currency fails even when no locale env var is set.
25	let money;
26	try {
27	  money = new Money(args.amount, args.currency);
28	} catch (err) {
29	  if (err instanceof CurrencyDoesNotExist) {
30	    process.stderr.write(
31	      `moneyed.classes.CurrencyDoesNotExist: No currency with code ${err.code} is defined.\n`
32	    );
33	    process.exit(1);
34	  }
35	  throw err;
36	}
37	
38	let rules;
39	try {
40	  rules = rulesForLocale(resolveLocaleId(process.env));
41	} catch (err) {
42	  if (err instanceof EmptyLocaleError) {
43	    process.stderr.write('TypeError: Empty locale identifier value: None\n');
44	    process.exit(1);
45	  }
46	  if (err instanceof UnknownLocaleError) {
47	    process.stderr.write(`babel.core.UnknownLocaleError: unknown locale '${err.id}'\n`);
48	    process.exit(1);
49	  }
50	  throw err;
51	}
52	
53	process.stdout.write(money.toString(rules) + '\n');
